logo='/assets/brand/mpbp440-corp-official.png'
contact='mailto:mpbp97440@gmail.com'
def header(active):
    links=[('index.html','Entreprise','corporate'),('musique.html','MPBP Music','music'),('engineering.html','Engineering','engineering')]
    return f'''<a class="skip" href="#main">Aller au contenu</a><div class="review">Direction V15 · Maquette à valider <a href="review.html">Dossier de validation</a></div><header class="header"><div class="wrap header-inner"><a class="brand" href="index.html"><img src="{logo}" alt="Logo officiel MPBP 440 Corp" width="56" height="56"><span><strong>MPBP 440 CORP.</strong><small>Création indépendante</small></span></a><button class="menu" aria-expanded="false" aria-controls="navigation" type="button">Menu</button><nav class="nav" id="navigation" aria-label="Navigation principale">'''+''.join(f'<a href="{url}"'+(' aria-current="page"' if active==key else '')+f'>{title}</a>' for url,title,key in links)+f'<a class="contact-link" href="{contact}">Parlons de votre projet</a></nav></div></header>'
def footer():return f'''<footer class="footer"><div class="wrap footer-inner"><div><strong>MPBP 440 Corp.</strong><p>Music · Passion · But · Progress</p></div><div class="footer-links"><a href="index.html">Portail corporate</a><a href="musique.html">Musique</a><a href="engineering.html">Engineering</a><a href="{contact}">Contact</a><a href="review.html">À propos de cette maquette</a></div><p>© 2026 MPBP 440 Corp.</p></div></footer>'''
def page(name,title,active,body):
    doc=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="theme-color" content="#050a10"><title>{esc(title)} · MPBP 440 Corp. · Maquette V15</title><link rel="icon" href="{logo}"><link rel="stylesheet" href="site.css"><script src="site.js" defer></script></head><body class="{active}">{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''
    doc=doc.replace('.png" alt="Capture','.jpg" alt="Capture').replace('.png" alt="Portail','.jpg" alt="Portail').replace('.png" alt="Musique','.jpg" alt="Musique').replace('.png" alt="Engineering','.jpg" alt="Engineering').replace('captures/corporate-390.png','captures/corporate-390.jpg').replace('captures/music-390.png','captures/music-390.jpg').replace('captures/engineering-390.png','captures/engineering-390.jpg')
    if name=='review.html':
        for screen in ('corporate','music','engineering'):
            for width in (390,1440):doc=doc.replace(f'src="captures/{screen}-{width}.jpg"',f'src="captures/{screen}-{width}-viewport.jpg"')
    (OUT/name).write_text(doc,encoding='utf-8')
